@Scheme.LocalEquations.divEq_of_stalkIdeal_eq : ∀ {X : Scheme} {d₁ d₂ : X.LocalEquations},
  (∀ (z : ↥X), d₁.stalkIdeal z = d₂.stalkIdeal z) → d₁.DivEq d₂
@Scheme.LocalEquations.stalkIdeal_eq_of_divEq : ∀ {X : Scheme} {d₁ d₂ : X.LocalEquations},
  d₁.DivEq d₂ → ∀ (z : ↥X), d₁.stalkIdeal z = d₂.stalkIdeal z
@divisorWindow_eq_of_divEq : ∀ {k : Type u_1} [inst : Field k] {C : CategoryTheory.Over (Spec (CommRingCat.of k))}
  {R : Type u_1} [inst_1 : CommRing R] [inst_2 : Algebra k R] {π : C.left ⟶ P1 k} [inst_3 : IsFinite π]
  [inst_4 : SmoothOfRelativeDimension 1 (C.left ↘ Spec (CommRingCat.of k))]
  [inst_5 : AlgebraicGeometry.IsIntegral C.left] [inst_6 : LocallyOfFiniteType (C.left ↘ Spec (CommRingCat.of k))]
  [inst_7 : QuasiCompact (C.left ↘ Spec (CommRingCat.of k))] [inst_8 : IsDominant π] {a : ℕ}
  {d₁ d₂ : (relCurve C R).LocalEquations},
  d₁.DivEq d₂ →
    ∀ (hH1 : Subsingleton (relTwistPair C k π (relThetaCocycle C k π a)).H1),
      divisorWindow d₁ hH1 = divisorWindow d₂ hH1
@Scheme.LocalEquations.divEq_refl : ∀ {X : Scheme} (d : X.LocalEquations), d.DivEq d
